UPDATE pms_sku_stock
SET lock_stock = lock_stock + #{quantity}
WHERE id = #{skuId}
  AND #{quantity} > 0
  AND stock IS NOT NULL
  AND lock_stock IS NOT NULL
  AND stock >= 0
  AND lock_stock >= 0
  AND stock >= lock_stock
  AND stock - lock_stock >= #{quantity}

UPDATE pms_sku_stock
SET stock = stock - #{quantity},
    lock_stock = lock_stock - #{quantity}
WHERE id = #{skuId}
  AND #{quantity} > 0
  AND stock IS NOT NULL
  AND lock_stock IS NOT NULL
  AND stock >= #{quantity}
  AND lock_stock >= #{quantity}

UPDATE pms_sku_stock
SET lock_stock = lock_stock - #{quantity}
WHERE id = #{skuId}
  AND #{quantity} > 0
  AND stock IS NOT NULL
  AND lock_stock IS NOT NULL
  AND lock_stock >= #{quantity}

UPDATE ums_member
SET integration = integration - #{amount}
WHERE id = #{memberId}
  AND #{amount} > 0
  AND integration IS NOT NULL
  AND integration >= #{amount}

UPDATE ums_member
SET integration = IFNULL(integration, 0) + #{amount}
WHERE id = #{memberId}
  AND #{amount} > 0

UPDATE sms_coupon_history
SET use_status = 1, use_time = NOW()
WHERE coupon_id = #{couponId}
  AND member_id = #{memberId}
  AND use_status = 0
LIMIT 1

UPDATE sms_coupon_history
SET use_status = 0, use_time = NULL
WHERE coupon_id = #{couponId}
  AND member_id = #{memberId}
  AND use_status = 1
LIMIT 1
